with (ROOT/'kamus_indikator.csv').open('w',encoding='utf-8-sig',newline='') as f:
    w=csv.DictWriter(f,fieldnames=rows[0].keys());w.writeheader();w.writerows(rows)
md=['# Kamus indikator dan kesiapan data','Semua rasio dikali 100 kecuali satuan lain dinyatakan. TERSEDIA berarti ada file numerik lokal; PERLU TABULASI berarti baru instrumen/sumbernya yang teridentifikasi. Angka kelompok belum diperkirakan dari contoh data.','| ID | Aspek | Indikator | Penyebut/satuan | Ketersediaan | Batas utama |','|---|---|---|---|---|---|']
for r in rows:md.append('| '+' | '.join([r['id'],r['aspek'],r['indikator'],r['penyebut'],r['ketersediaan'],r['batas']])+' |')
md.append('\nPembilang, sumber ID dan penjelasan lengkap tersedia dalam `kamus_indikator.csv`. Pilih indikator berdasarkan pertanyaan; jangan menjumlahkan semuanya menjadi skor urgensi tanpa dasar.')
(ROOT/'03_kamus_indikator.md').write_text('\n'.join(md)+'\n',encoding='utf-8')
